/* cppi::cc397de9ff9d95d738e785f64bdf69eb7951c6852795036548862e4f8d8ceeb4 */
SELECT COUNT(*) FROM (WITH filtered_index AS (SELECT business_date, id_cppib_index, index_description, rimes_source_code, rimes_source_description, index_value_base, return_daily_base, inception_return_base, feed_version FROM market.cppib_index WHERE id_cppib_index = 'G0O1_TR_CAD_0_0' AND business_date BETWEEN DATE '2025-04-30' AND DATE '2025-06-02') SELECT f.business_date, f.id_cppib_index, f.index_description, f.return_daily_base, f.inception_return_base FROM filtered_index f JOIN (SELECT business_date, max(feed_version) AS feed_version FROM filtered_index GROUP BY business_date) latest ON f.business_date = latest.business_date AND f.feed_version = latest.feed_version
) dbvrcnt

